using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: Default discriminator property renamed
            // from "Discriminator" to "$type" in EF Core 9.
            // Preserve the old name so existing documents are still found.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: HasIndex throws on the Cosmos provider
            // in EF Core 9 (Cosmos DB does not support secondary indexes
            // managed by EF). Remove the call entirely.
            // was: entity.HasIndex(b => b.Name);

            // Breaking change 3: Document "id" no longer uses the
            // "{Discriminator}|{Key}" format (e.g. "Blog|1").
            // EF Core 9 uses only the key value.  Map a computed shadow
            // property to the JSON "id" so reads/writes match the
            // existing "Blog|<key>" values already stored in Cosmos DB.
            entity.Property<string>("__id")
                  .ToJsonProperty("id")
                  .HasValueGeneratorFactory<BlogIdGeneratorFactory>();
        });
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

// Generates the legacy "Blog|{key}" id format for new documents and
// allows EF Core 9 to round-trip existing ones.
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class BlogIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"Blog|{entry.Property("Id").CurrentValue}";
}

class BlogIdGeneratorFactory : ValueGeneratorFactory
{
    public override ValueGenerator Create(
        Microsoft.EntityFrameworkCore.Metadata.IProperty property,
        Microsoft.EntityFrameworkCore.Metadata.ITypeBase typeBase)
        => new BlogIdGenerator();
}

